    // Load kernel parameters
    // -------------------------------------------------
    ld.param.u64    %rd1, [input_ptr];
    ld.param.u64    %rd2, [output_ptr];
    ld.param.u64    %rd3, [N];

    // -------------------------------------------------
    // Compute global thread index
    // -------------------------------------------------
    mov.u32         %r1, %tid.x;        // threadIdx.x
    mov.u32         %r2, %ctaid.x;      // blockIdx.x
    mov.u32         %r3, %ntid.x;       // blockDim.x
    mul.lo.u32      %r4, %r2, %r3;      // blockIdx.x * blockDim.x
    add.u32         %r5, %r4, %r1;      // global linear index

    // -------------------------------------------------
    // Bounds check
    // -------------------------------------------------
    cvt.u64.u32     %rd4, %r5;
    setp.ge.u64     %p1, %rd4, %rd3;
    @%p1           bra DONE;

    // -------------------------------------------------
    // Load fp16 element, convert to fp32
    // -------------------------------------------------
    // address = base + idx * sizeof(half) (2 bytes)
    mul.wide.u32    %rd5, %r5, 2;
    add.u64         %rd6, %rd1, %rd5;   // input address
    ld.global.u16   %h0, [%rd6];
    cvt.f32.f16     %f0, %h0;           // x as fp32

    // -------------------------------------------------
    // GELU approximate: 0.5 * x * (1 + tanh( sqrt(2/pi)*(x + 0.044715*x^3) ))
    // -------------------------------------------------
    // constants
    mov.f32         %f1, 0.5;                     // 0.5
    mov.f32         %f2, 0.044715;                // 0.044715
    mov.f32         %f3, 0.7978845608028654;      // sqrt(2/pi)

    // x^3
    mul.f32         %f4, %f0, %f0;                // x^2
    mul.f32         %f5, %f4, %f0;                // x^3

